/** Firmware metadata is generated by tools/engine-metadata.c at engine build time. */
export interface ParameterDescriptor { name: string; min: number; max: number; default: number }
export interface FirmwareMetadata {
 fm6Factory: number[][];
 sampleRate: number;
 blockFrames: number;
 steps: number;
 engineParamOffset: number;
 parameters: ParameterDescriptor[];
 globals: ParameterDescriptor[];
 engines: {name: string; parameters: ParameterDescriptor[]; presets: {name: string; parameters: number[]}[]}[];
}
export async function loadMetadata(): Promise<FirmwareMetadata> {
 const response = await fetch('/engine/metadata.json');
 if (!response.ok) throw new Error('Build the SLOOP engine first: python3 scripts/build-engine.py --docker --test');
 const metadata: FirmwareMetadata = await response.json();
 if (metadata.steps !== 64 || metadata.sampleRate !== 44100 || metadata.engines.length !== 12) throw new Error('Unsupported SLOOP engine build');
 return metadata;
}
